/**
 * emit to subscription queries of type FindAccessPolicy,
 * but only if the id matches
 *
 * @param		entity	AccessPolicy
 */
	protected void emitFindAccessPolicy( AccessPolicy entity ) {
		LOGGER.info("handling emitFindAccessPolicy" );
		
	    queryUpdateEmitter.emit(FindAccessPolicyQuery.class,
	                            query -> query.getFilter().getAccessPolicyId().equals(entity.getAccessPolicyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAccessPolicy
	 * 
	 * @param		entity	AccessPolicy
	 */
	protected void emitFindAllAccessPolicy( AccessPolicy entity ) {
		LOGGER.info("handling emitFindAllAccessPolicy" );
		
	    queryUpdateEmitter.emit(FindAllAccessPolicyQuery.class,
	                            query -> true,
	                            entity);
	}

